import{_ as l,o as a,c as i,ae as o}from"./chunks/framework.CSxHcPWC.js";const p=JSON.parse('{"title":"📋 Deployment Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/deployment_checklist.md","filePath":"deployment/deployment_checklist.md"}'),t={name:"deployment/deployment_checklist.md"};function r(n,e,s,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="📋-deployment-checklist" tabindex="-1">📋 Deployment Checklist <a class="header-anchor" href="#📋-deployment-checklist" aria-label="Permalink to &quot;📋 Deployment Checklist&quot;">​</a></h1><p>Use this checklist to ensure a smooth deployment of your WealthFam instance.</p><h2 id="pre-deployment" tabindex="-1">Pre-Deployment <a class="header-anchor" href="#pre-deployment" aria-label="Permalink to &quot;Pre-Deployment&quot;">​</a></h2><h3 id="repository-setup" tabindex="-1">Repository Setup <a class="header-anchor" href="#repository-setup" aria-label="Permalink to &quot;Repository Setup&quot;">​</a></h3><ul><li>[ ] Code is pushed to GitHub/GitLab</li><li>[ ] Repository is public OR deployment platform has access</li><li>[ ] <code>.env.example</code> is committed (never commit <code>.env</code> with secrets!)</li><li>[ ] <code>version.json</code> is up to date</li><li>[ ] All deployment config files are present: <ul><li>[ ] <code>Dockerfile</code></li><li>[ ] <code>docker-compose.yml</code></li><li>[ ] <code>.dockerignore</code></li><li>[ ] <code>koyeb.json</code> (for Koyeb)</li><li>[ ] <code>railway.json</code> (for Railway)</li><li>[ ] <code>render.yaml</code> (for Render)</li><li>[ ] <code>fly.toml</code> (for Fly.io)</li></ul></li></ul><h3 id="docker-image-if-self-hosting" tabindex="-1">Docker Image (if self-hosting) <a class="header-anchor" href="#docker-image-if-self-hosting" aria-label="Permalink to &quot;Docker Image (if self-hosting)&quot;">​</a></h3><ul><li>[ ] Docker image builds successfully: <code>docker build -t wealthfam:test .</code></li><li>[ ] Test run works: <code>docker run -p 8080:80 wealthfam:test</code></li><li>[ ] Health endpoint responds: <code>curl http://localhost:8080/health</code></li><li>[ ] Push to registry: <code>docker push wglabz/wealthfam:latest</code></li></ul><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><ul><li>[ ] <code>DATABASE_URL</code> configured for persistent volume</li><li>[ ] <code>SECRET_KEY</code> generated (for production): <code>openssl rand -hex 32</code></li><li>[ ] <code>GEMINI_API_KEY</code> obtained (optional): <a href="https://makersuite.google.com/app/apikey" target="_blank" rel="noreferrer">https://makersuite.google.com/app/apikey</a></li><li>[ ] Email sync credentials ready (optional)</li><li>[ ] All required env vars documented in platform secrets</li></ul><h2 id="deployment-steps" tabindex="-1">Deployment Steps <a class="header-anchor" href="#deployment-steps" aria-label="Permalink to &quot;Deployment Steps&quot;">​</a></h2><h3 id="choose-your-platform" tabindex="-1">Choose Your Platform <a class="header-anchor" href="#choose-your-platform" aria-label="Permalink to &quot;Choose Your Platform&quot;">​</a></h3><h4 id="koyeb" tabindex="-1">Koyeb <a class="header-anchor" href="#koyeb" aria-label="Permalink to &quot;Koyeb&quot;">​</a></h4><ul><li>[ ] Click deploy button or use Koyeb CLI</li><li>[ ] Configure persistent volume at <code>/data</code> (1GB minimum)</li><li>[ ] Set environment variables</li><li>[ ] Enable health checks at <code>/health</code></li><li>[ ] Select region (fra recommended)</li><li>[ ] Deploy and wait for build</li></ul><h4 id="railway" tabindex="-1">Railway <a class="header-anchor" href="#railway" aria-label="Permalink to &quot;Railway&quot;">​</a></h4><ul><li>[ ] Connect GitHub repository</li><li>[ ] Add PostgreSQL/volume storage</li><li>[ ] Configure environment variables</li><li>[ ] Enable Dockerfile build</li><li>[ ] Generate domain or add custom domain</li><li>[ ] Deploy</li></ul><h4 id="render" tabindex="-1">Render <a class="header-anchor" href="#render" aria-label="Permalink to &quot;Render&quot;">​</a></h4><ul><li>[ ] Create new Web Service</li><li>[ ] Connect repository</li><li>[ ] Select Docker runtime</li><li>[ ] Add persistent disk at <code>/data</code> (1GB)</li><li>[ ] Configure environment variables</li><li>[ ] Set health check path: <code>/health</code></li><li>[ ] Deploy</li></ul><h4 id="fly-io" tabindex="-1">Fly.io <a class="header-anchor" href="#fly-io" aria-label="Permalink to &quot;Fly.io&quot;">​</a></h4><ul><li>[ ] Install flyctl: <code>curl -L https://fly.io/install.sh | sh</code></li><li>[ ] Login: <code>flyctl auth login</code></li><li>[ ] Launch app: <code>flyctl launch</code></li><li>[ ] Create volume: <code>flyctl volumes create wealthfam_data --size 1</code></li><li>[ ] Deploy: <code>flyctl deploy</code></li></ul><h4 id="self-hosted-docker" tabindex="-1">Self-Hosted (Docker) <a class="header-anchor" href="#self-hosted-docker" aria-label="Permalink to &quot;Self-Hosted (Docker)&quot;">​</a></h4><ul><li>[ ] SSH into server</li><li>[ ] Install Docker and Docker Compose</li><li>[ ] Clone repository or download files</li><li>[ ] Create <code>.env</code> from <code>.env.example</code></li><li>[ ] Run: <code>docker-compose up -d</code></li><li>[ ] Verify: <code>docker-compose logs -f</code></li></ul><h2 id="post-deployment" tabindex="-1">Post-Deployment <a class="header-anchor" href="#post-deployment" aria-label="Permalink to &quot;Post-Deployment&quot;">​</a></h2><h3 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h3><ul><li>[ ] Application is accessible at deployment URL</li><li>[ ] Health check passes: <code>/health</code> returns <code>{&quot;status&quot;: &quot;healthy&quot;}</code></li><li>[ ] API docs accessible: <code>/api/v1/docs</code></li><li>[ ] Frontend loads without errors</li><li>[ ] Can register/login successfully</li><li>[ ] Database persists across restarts</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>[ ] HTTPS is enabled (most platforms do this automatically)</li><li>[ ] Default admin password changed (if applicable)</li><li>[ ] Environment secrets are not exposed in logs</li><li>[ ] CORS is properly configured for your domain</li><li>[ ] Rate limiting is enabled (if available on platform)</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>[ ] Response times are acceptable</li><li>[ ] Health checks are passing consistently</li><li>[ ] Database queries are optimized</li><li>[ ] Frontend assets are being served correctly</li><li>[ ] Consider upgrading instance if needed</li></ul><h3 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h3><ul><li>[ ] Set up uptime monitoring (UptimeRobot, Pingdom, etc.)</li><li>[ ] Configure error tracking (Sentry, etc.)</li><li>[ ] Enable platform logs/metrics</li><li>[ ] Set up backup strategy for <code>/data</code> volume</li><li>[ ] Document rollback procedure</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>[ ] Update README with your deployment URL</li><li>[ ] Document any custom configuration</li><li>[ ] Share credentials with team (securely!)</li><li>[ ] Create runbook for common issues</li></ul><h2 id="testing-production" tabindex="-1">Testing Production <a class="header-anchor" href="#testing-production" aria-label="Permalink to &quot;Testing Production&quot;">​</a></h2><h3 id="functional-tests" tabindex="-1">Functional Tests <a class="header-anchor" href="#functional-tests" aria-label="Permalink to &quot;Functional Tests&quot;">​</a></h3><ul><li>[ ] User registration works</li><li>[ ] Login/logout works</li><li>[ ] Can create transactions</li><li>[ ] Can upload bank statements</li><li>[ ] AI parsing works (if Gemini key provided)</li><li>[ ] Email sync works (if configured)</li><li>[ ] Mobile app can connect</li><li>[ ] Charts and analytics display correctly</li></ul><h3 id="data-persistence" tabindex="-1">Data Persistence <a class="header-anchor" href="#data-persistence" aria-label="Permalink to &quot;Data Persistence&quot;">​</a></h3><ul><li>[ ] Create test transaction</li><li>[ ] Restart container/app</li><li>[ ] Verify data is still there</li><li>[ ] Check database file exists in volume</li></ul><h2 id="mobile-app-setup" tabindex="-1">Mobile App Setup <a class="header-anchor" href="#mobile-app-setup" aria-label="Permalink to &quot;Mobile App Setup&quot;">​</a></h2><ul><li>[ ] Download latest APK from releases</li><li>[ ] Configure backend URL in app settings</li><li>[ ] Test SMS ingestion</li><li>[ ] Verify device approval flow</li><li>[ ] Test biometric login (if enabled)</li></ul><h2 id="backup-strategy" tabindex="-1">Backup Strategy <a class="header-anchor" href="#backup-strategy" aria-label="Permalink to &quot;Backup Strategy&quot;">​</a></h2><ul><li>[ ] Set up automated backups of <code>/data</code> volume</li><li>[ ] Test restore procedure</li><li>[ ] Document backup schedule</li><li>[ ] Store backups in different location</li><li>[ ] Consider database export scripts</li></ul><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><h3 id="regular-tasks" tabindex="-1">Regular Tasks <a class="header-anchor" href="#regular-tasks" aria-label="Permalink to &quot;Regular Tasks&quot;">​</a></h3><ul><li>[ ] Weekly: Check logs for errors</li><li>[ ] Monthly: Review resource usage</li><li>[ ] Monthly: Update to latest version</li><li>[ ] Quarterly: Review and rotate secrets</li><li>[ ] Quarterly: Database optimization/vacuum</li></ul><h3 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h3><ul><li>[ ] Pull latest image: <code>docker pull wglabz/wealthfam:latest</code></li><li>[ ] Backup data before update</li><li>[ ] Apply update: <code>docker-compose up -d --force-recreate</code></li><li>[ ] Verify health: <code>/health</code></li><li>[ ] Test critical features</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h3><ul><li>[ ] If health check fails → Check database volume permissions</li><li>[ ] If frontend is blank → Check browser console for errors</li><li>[ ] If API returns 500 → Check application logs</li><li>[ ] If image won&#39;t pull → Verify Docker Hub credentials</li><li>[ ] If volume data lost → Check mount path configuration</li></ul><h3 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h3><ul><li>[ ] Check <a href="./DEPLOYMENT.html">Deployment Guide</a></li><li>[ ] Search <a href="https://github.com/WealthFam/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>[ ] Ask on <a href="https://discord.gg/wealthfam" target="_blank" rel="noreferrer">Discord</a></li><li>[ ] Email: support@wealthfam.app</li></ul><h2 id="rollback-plan" tabindex="-1">Rollback Plan <a class="header-anchor" href="#rollback-plan" aria-label="Permalink to &quot;Rollback Plan&quot;">​</a></h2><p>In case of issues:</p><ol><li>[ ] Document the issue</li><li>[ ] Stop current deployment</li><li>[ ] Revert to previous version/tag</li><li>[ ] Restore database backup (if needed)</li><li>[ ] Verify health check</li><li>[ ] Notify users (if applicable)</li></ol><hr><h2 id="✅-deployment-complete" tabindex="-1">✅ Deployment Complete! <a class="header-anchor" href="#✅-deployment-complete" aria-label="Permalink to &quot;✅ Deployment Complete!&quot;">​</a></h2><p>Congratulations! Your WealthFam instance is live.</p><p><strong>Next Steps:</strong></p><ol><li>Share the URL with your team</li><li>Configure integrations (email, AI)</li><li>Import historical data</li><li>Set up mobile apps</li><li>Start tracking your finances!</li></ol><hr><p><em>Last Updated: 2026-01-27</em></p>',61)])])}const m=l(t,[["render",r]]);export{p as __pageData,m as default};
